/// Distinct names, sorted like live's pickers (alphabetical, ignoring case).
fn uniq<'a>(it: impl Iterator<Item = &'a str>) -> Vec<&'a str> {
    let mut out: Vec<&str> = Vec::new();
    for s in it {
        if !out.contains(&s) {
            out.push(s);
        }
    }
    out.sort_by_key(|s| s.to_lowercase());
    out
}

/// The component the tab starts with: the first of every picker
/// ("ANSI inch › Bolts & screws › Countersunk bolts › Countersunk bolt").
pub fn default_component() -> &'static Component {
    let standard = standards()[0];
    let category = categories(standard)[0];
    let class = classes(standard, category)[0];
    components(standard, category, class)[0]
}

/// Standards, alphabetical.
pub fn standards() -> Vec<&'static str> {
    uniq(CATALOGUE.iter().map(|c| c.standard.as_str()))
}

pub fn categories(standard: &str) -> Vec<&'static str> {
    uniq(CATALOGUE.iter().filter(|c| c.standard == standard).map(|c| c.category.as_str()))
}

pub fn classes(standard: &str, category: &str) -> Vec<&'static str> {
    uniq(CATALOGUE.iter().filter(|c| c.standard == standard && c.category == category).map(|c| c.class.as_str()))
}

pub fn components(standard: &str, category: &str, class: &str) -> Vec<&'static Component> {
    let mut out: Vec<&'static Component> = CATALOGUE.iter().filter(|c| c.standard == standard && c.category == category && c.class == class).collect();
    out.sort_by_key(|c| c.name.to_lowercase());
    out
}

/// The catalogue entry of a spec.
pub fn component(spec: &StandardSpec) -> Option<&'static Component> {
    CATALOGUE.iter().find(|c| c.standard == spec.standard && c.category == spec.category && c.class == spec.class && c.name == spec.component)
}

impl StandardSpec {
    /// A spec for a component with its default size and that size's first
    /// length (live).
    pub fn new(c: &Component) -> Self {
        let size = c.default_size();
        StandardSpec {
            standard: c.standard.clone(),
            category: c.category.clone(),
            class: c.class.clone(),
            component: c.name.clone(),
            size: size.name.clone(),
            length: c.default_length(size),
            params: BTreeMap::new(),
            material: None,
            finish: None,
        }
    }

    /// A select's value (the component's default unless chosen; for a
    /// select depending on the size, the first of that size's options
    /// unless the chosen one is among them).
    pub fn param(&self, label: &str) -> &str {
        // The size's row for the other chosen options (tapping screws: the
        // Threads/inch list depends on the Tip type).
        let size_options = component(self)
            .and_then(|c| {
                let mut rows = c.sizes.iter().filter(|s| s.name == self.size);
                let first = rows.clone().next()?;
                let chosen = |k: &String| self.params.get(k).cloned().or_else(|| c.params.iter().find(|p| &p.label == k).map(|p| p.default.clone()));
                Some(rows.find(|s| s.when.iter().filter(|(k, _)| k.as_str() != label).all(|(k, v)| chosen(k).as_deref() == Some(v.as_str()))).unwrap_or(first))
            })
            .and_then(|s| s.values.get(label));
        if let Some(v) = self.params.get(label)
            && size_options.is_none_or(|o| o.contains(v))
        {
            return v;
        }
        if let Some(first) = size_options.and_then(|o| o.first()) {
            return first;
        }
        component(self).and_then(|c| c.params.iter().find(|p| p.label == label)).map(|p| p.default.as_str()).unwrap_or("")
    }

    /// The size row for the chosen size and parameters.
    pub fn size_row(&self) -> Option<&'static Size> {
        let c = component(self)?;
        let mut rows = c.sizes.iter().filter(|s| s.name == self.size);
        let first = rows.next()?;
        Some(std::iter::once(first).chain(rows).find(|s| s.when.iter().all(|(k, v)| self.param(k) == v)).unwrap_or(first))
    }

    /// The part's name, which instances take ("<Name> <n>") and the
    /// Description starts with (live): the size row's label ("Hex socket
    /// head cap screw M6x1.00", "Type A flat washer 3/8 Narrow") and
    /// " x <length>".
    pub fn part_name(&self) -> String {
        let mut label = self.size_row().map(|s| s.label.clone()).unwrap_or_else(|| format!("{} {}", self.component, self.size));
        // Live names the chosen option where the label carries the default
        // ("Parallel key A x 2 x 2" -> "Parallel key B x 2 x 2").
        if let Some(c) = component(self) {
            for p in &c.params {
                let chosen = self.param(&p.label);
                let token = format!(" {} x ", p.default);
                if chosen != p.default && !p.default.is_empty() && label.contains(&token) {
                    label = label.replacen(&token, &format!(" {chosen} x "), 1);
                }
            }
        }
        // "{l}" marks where live puts the length ("Socket head shoulder
        // screw 6.5 x 10 x M5x0.8"); else it ends the name.
        match &self.length {
            Some(l) if label.contains("{l}") => label.replace("{l}", l),
            Some(l) => format!("{label} x {l}"),
            None => label.replace(" x {l}", ""),
        }
    }

    /// Washer Series.
    pub fn series(&self) -> &str {
        self.param("Series")
    }

    /// Nut Bearing face.
    pub fn bearing_face(&self) -> &str {
        self.param("Bearing face")
    }

    pub fn material(&self) -> &str {
        self.material.as_deref().unwrap_or_else(|| component(self).and_then(|c| c.materials().first().copied()).unwrap_or(MATERIALS[0]))
    }

    pub fn finish(&self) -> &str {
        self.finish.as_deref().unwrap_or_else(|| component(self).and_then(|c| c.finishes().first().copied()).unwrap_or(FINISHES[0]))
    }

    /// The Description field and BOM column, like live's "Countersunk Bolt
    /// #10-24 x 0.25 Stainless Steel " (the part name, the material, the
    /// finish unless Plain).
    pub fn description(&self) -> String {
        let plain = component(self).and_then(|c| c.finishes().first().copied()).unwrap_or(FINISHES[0]);
        let finish = if self.finish() == plain { "" } else { self.finish() };
        format!("{} {} {finish}", self.part_name(), self.material())
    }

    /// Change the size, keeping the length when it is still offered.
    pub fn set_size(&mut self, size: &str) {
        self.size = size.to_string();
        self.fix_length();
    }

    /// Keep the length when the size row (for the chosen options) still
    /// offers it, else take the row's default length.
    pub fn fix_length(&mut self) {
        if let Some(c) = component(self)
            && let Some(s) = self.size_row()
        {
            let lengths = c.lengths(s);
            // A typed length (live's EDIT box) stays.
            if c.length_edit && self.length.as_deref().and_then(|l| l.trim().parse::<f64>().ok()).is_some_and(|v| v > 0.0) {
                return;
            }
            if self.length.as_ref().is_none_or(|l| !lengths.contains(l)) {
                self.length = c.default_length(s);
            }
        }
    }
}

/// The spec as configuration values (keeps BOM rows of different sizes apart).
pub fn config_values(spec: &StandardSpec) -> ConfigValues {
    let mut v = ConfigValues::default();
    v.0.insert("Component".into(), spec.component.clone());
    v.0.insert("Size".into(), spec.size.clone());
    if let Some(l) = &spec.length {
        v.0.insert("Length".into(), l.clone());
    }
    for (k, p) in &spec.params {
        v.0.insert(k.clone(), p.clone());
    }
    v
}

/// Auto-size: the size fitting a hole or shaft of diameter `d` (meters).
/// Bolts and screws round down (no interference), nuts and washers round up
/// (washers by their bolt size, which rounds down).
pub fn auto_size(c: &'static Component, d: f64) -> Option<&'static str> {
    let tol = 1e-6;
    let dm = |s: &Size| c.diameter_m(s);
    let pick = if c.shape == Shape::Washer || !c.shape.fits_over() {
        c.sizes.iter().filter(|s| dm(s) <= d + tol && dm(s) >= d * 0.6).max_by(|a, b| dm(a).total_cmp(&dm(b)))
    } else {
        c.sizes.iter().filter(|s| dm(s) >= d - tol).min_by(|a, b| dm(a).total_cmp(&dm(b)))
    };
    pick.map(|s| s.name.as_str())
}

/// Message when auto-size finds nothing (Onshape's wording).
pub const NO_MATCHING_SIZE: &str = "Unable to find matching size for selection. Selection may be too small or large for specific component";








/// Mate connector of a standard part (index 0: under the head / bottom face;
/// 1: top face of nuts and washers).
pub fn connector_reference(index: u64) -> crate::reference::Reference {
    crate::reference::Reference::MateConnector { feature: FeatureId(PART_FEATURE.0 + 1 + index), index: 0 }
}



